using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

// Provided infrastructure — do not modify.
public interface IOrderStore
{
    int GetStock(string sku);
    void Reserve(string sku, int qty);
}

public sealed class SqlOrderStore : IOrderStore   // the "real" backend, simulated
{
    public System.Collections.Generic.Dictionary<string, int> Stock = new();
    public System.Collections.Generic.List<string> Reservations = new();
    public int GetStock(string sku) => Stock.TryGetValue(sku, out var n) ? n : 0;
    public void Reserve(string sku, int qty) => Reservations.Add(sku + ":" + qty);
}

